    </form>
    {/* Portaled: the sticky header's backdrop blur would otherwise confine the fixed panel. */}
    {loaded && createPortal(<AiPanelDialog open={open} seed={seed} onClose={() => setOpen(false)} />, document.body)}
  </>;
}

